"""Filesystem watcher for save game directories."""
import logging
from pathlib import Path
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

logger = logging.getLogger(__name__)


class SaveFileHandler(FileSystemEventHandler):
    def __init__(self, callback):
        self.callback = callback
        self._debounce_timer = None

    def on_modified(self, event):
        if event.is_directory:
            return
        path = Path(event.src_path)
        if path.suffix in ('.sav', '.save', '.dat', '.json'):
            logger.info(f'Detected change: {path.name}')
            self.callback(path)


class FsWatcher:
    def __init__(self, watch_dirs: list[Path], on_change):
        self._observer = Observer()
        for d in watch_dirs:
            self._observer.schedule(
                SaveFileHandler(on_change), str(d), recursive=True
            )

    def start(self):
        self._observer.start()
        logger.info('Filesystem watcher started')

    def stop(self):
        self._observer.stop()
        self._observer.join()

